      '-filter_complex',
      `[1:a]volume=${gain}[bg];[0:a][bg]amix=inputs=2:duration=first:dropout_transition=0[aout]`,
      '-map', '0:v:0', '-map', '[aout]',
      '-c:v', 'copy', '-c:a', 'aac', '-b:a', '192k', '-shortest', outPath,
    ];
  }
  return [
    ...base,
    '-filter_complex', `[1:a]volume=${gain}[aout]`,
    '-map', '0:v:0', '-map', '[aout]',
    '-c:v', 'copy', '-c:a', 'aac', '-b:a', '192k', '-shortest', outPath,
  ];
