      "path": "lib/platforms.js",
      "content": "/**\n * dsh-douyin-publish · platforms —— 每个平台一份\"档案\"：地址、控件选择器、能力边界。\n *\n * 为什么单独一份：抖音和 B站的投稿页结构完全不同（B站甚至不换 URL 就切到编辑页，\n * 标题框会预填文件名，话题是\"标签\"而不是简介里的 #话题）。把这些差异塞进\n * if/else 会很快烂掉；一份声明式的档案能让\"新增第三个平台\"只动这一个文件。\n *\n * **verified 的含义**：`true` = 作者在真机（真登录态）上把整条链路跑通并核对过选择器。\n * 没核对过的一律 `false`，调用即明确拒绝 —— 不拿别的平台的选择器去瞎点。\n *\n * @module dsh-douyin-publish/platforms\n */\n\n/** 文件是怎么交给页面的。 */\nexport const ATTACH_MODES = Object.freeze({\n  /** 本机起一个只读的 127.0.0.1 小服务，页面用 fetch 取回来、用 DataTransfer 塞进 input。 */\n  inject: 'inject',\n  /** 真实点击上传按钮，等系统\"打开文件\"对话框，用 UI 自动化填路径（老办法，大文件/注入被拦时的退路）。 */\n  dialog: 'dialog',\n});\n\nexport const PLATFORMS = Object.freeze({\n  douyin: {\n    key: 'douyin',\n    label: '抖音',\n    verified: true,\n    uploadUrl: 'https://creator.douyin.com/creator-micro/content/upload',\n    /** 进入编辑页后 URL 会带这个片段（B站不换 URL，所以它是可选的旁证）。 */\n    editUrlMark: '/content/post/video',\n    attach: {\n      inputSelector: 'input[type=file]',\n      /** 注入失败或文件太大时的退路：真点这个按钮，等系统对话框。 */\n      dialogText: '上传视频',\n    },\n    selectors: {\n      title: 'input[placeholder*=\"作品标题\"]',\n      caption: '[contenteditable=\"true\"]',\n      coverEntry: '选择封面',\n      submitText: '发布',\n      draftText: '暂存离开',\n      /** 平台曲库入口：点开之后由人自己在里面搜歌/试听/使用。 */\n      musicEntry: ['添加音乐', '选择音乐'],\n      /**\n       * 曲库面板（2026-10-18 真机核对）：入口其实是右侧那颗「添加音乐」标签\n       * （class 里有 preview-button），点开是一个 \"选择音乐\" 侧边面板，里面有「搜索音乐」框。\n       */\n      musicPanel: {\n        entrySelector: 'div[class*=preview-button]',\n        searchInput: 'input[placeholder*=\"搜索音乐\"]',\n      },\n    },\n    /** 编辑页\"就绪\"的判据（页面里执行）。 */\n    editReady: '!!document.querySelector(\\'input[placeholder*=\"作品标题\"]\\')',\n    /** 可见性：页面上真实存在的中文文案 → 值。 */\n    visibility: { public: '公开', friends: '好友可见', private: '仅自己可见' },\n    /** 话题怎么落地：inline = 写进简介（\"#话题 \"）。 */\n    topicMode: 'inline',\n    supports: { visibility: true, cover: true },\n  },\n\n  bilibili: {\n    key: 'bilibili',\n    label: 'B站',\n    verified: true,\n    uploadUrl: 'https://member.bilibili.com/platform/upload/video/frame',\n    /** B站投稿页上传完成后**不换 URL**，编辑表单是同一个页面上长出来的 —— 所以不能靠 URL 判断。 */\n    editUrlMark: null,\n    attach: {\n      inputSelector: 'input[type=file]',\n      dialogText: '上传视频',\n    },\n    selectors: {\n      title: 'input.input-val[placeholder*=\"稿件标题\"]',\n      tagInput: 'input.input-val[placeholder*=\"创建标签\"]',\n      caption: '.ql-editor[data-placeholder*=\"填写更全面\"]',\n      coverEntry: '添加封面',\n      submitText: '立即投稿',\n      draftText: '存草稿',\n      /** \"更多设置\"折叠面板的展开把手。 */\n      moreToggle: 'span.label',\n      /** 可见范围的两个选项（在\"更多设置\"里）。 */\n      visibilityOption: 'span.check-radio-v2-name',\n    },\n    editReady: '!!document.querySelector(\\'input.input-val[placeholder*=\"稿件标题\"]\\')',\n    /**\n     * 投稿页上\"本地浏览器存在 N 个未提交的视频 → 继续编辑 / 不用了\"的提示。\n     * 自动化发布不该接管别人的旧草稿：点「不用了」，从新稿开始。\n     */\n    resumePrompt: { selector: '.entrance-tip', dismissText: '不用了' },\n    /** B站：公开可见 / 仅自己可见（在\"更多设置 → 可见范围\"里）。 */\n    visibility: { public: '公开可见', private: '仅自己可见' },\n    /** B站没有\"好友可见\"。 */\n    topicMode: 'tags',\n    supports: { visibility: true, cover: false },\n  },\n\n  xiaohongshu: {\n    key: 'xiaohongshu',\n    label: '小红书',\n    verified: false,\n    uploadUrl: 'https://creator.xiaohongshu.com/publish/publish',\n    attach: {},\n    selectors: {},\n    editReady: 'false',\n    visibility: {},\n    topicMode: 'inline',\n    supports: {},\n  },\n\n  x: {\n    key: 'x',\n    label: 'X（推特）',\n    verified: false,\n    uploadUrl: 'https://x.com/compose/post',\n    attach: {},\n    selectors: {},\n    editReady: 'false',\n    visibility: {},\n    topicMode: 'inline',\n    supports: {},\n  },\n});\n\n/** 平台键列表。 */\nexport const PLATFORM_KEYS = Object.keys(PLATFORMS);\n\n/**\n * 取平台档案。\n * @param {string} key 平台键\n * @returns {object} 档案（未知键回落到抖音）\n */\nexport function platformOf(key) {\n  return Object.hasOwn(PLATFORMS, String(key)) ? PLATFORMS[String(key)] : PLATFORMS.douyin;\n}\n"
    },
    {
      "path": "lib/index.js",
      "content": "/**\n * dsh-douyin-publish —— 宿主入口。\n *\n * 一句话：**把一段本地视频一路送到抖音投稿页的\"待发布\"状态** ——\n * 开投稿页、真实点上传、把文件交给系统对话框（含回读校验）、填标题、设可见性，\n * 然后**默认停手**：发布按钮不点。\n *\n * 两条默认值是刻意的：\n *   - 可见性默认 **仅自己可见**；要公开得显式说；\n *   - 模式默认 **draft**：填好就停，要真发得显式说 `mode=publish`。\n * 发布是不可逆且对外可见的动作 —— 默认必须保守。\n *\n * @module dsh-douyin-publish\n */\n\nimport { PLATFORMS, VISIBILITY, renderResult } from './plan.js';\nimport { uploadVideo } from './pipeline.js';\n\n/** 插件身份。 */\nexport const name = 'dsh-douyin-publish';\n\n/** 需要宿主提供的服务（browser 用 ctx.get 拿 —— 拿不到就给出明确错误，而不是让插件加载失败）。 */\nexport const inject = ['tools', 'systemPrompt'];\n\nconst SECTION_ORDER = 209;\nconst TOOL_TIMEOUT_MS = 300000;\n\n/** 面向模型的公告（常驻那一段）。 */\nexport const DOUYIN_GUIDANCE = [\n  '本机已安装 **dsh-douyin-publish（视频发布器 · 抖音 / B站）**：`douyin_upload` 把一段本地视频送到投稿页 —— 打开投稿页 → 版式自检 → **把文件塞进页面自己的上传控件**（本机临时小服务 + DataTransfer，不弹系统对话框；大文件或注入被拦时才退回对话框）→ 填标题 → 代填文案/话题 → 设可见性 → **默认停在投稿前**。',\n  `**两条默认值是刻意的**：可见性默认 \\`private\\`（${VISIBILITY.private.label}）、模式默认 \\`draft\\`（**不点投稿**）。要真发必须显式 `+\"`mode: 'publish'`\"+`，要公开必须显式 `+\"`visibility: 'public'`\"+`。`,\n  '**平台**：`platform` 可给 `douyin`（默认）或 `bilibili` —— 这两个都在真机上核对过。B站的**话题会进\"标签\"**（回车确认），可见范围在「更多设置 → 可见范围」里；`coverTime` 只对抖音生效。小红书 / X 还没核对，传了会明确拒绝。',\n  '**封面默认取第 1 秒**（第 0 帧常是黑场）；`coverTime: 0` 不动封面。',\n  '**配乐**：`bgmPath` 给一段本地音频就会先用 ffmpeg 混好再上传（原视频不动），`bgmVolume` 默认 0.35；**文案**：`description` 填进简介。',\n  '**版式自检**：投稿页/编辑页的关键控件缺一个就直接报 `layout-changed`（并点名缺什么），不会跑到一半停住。',\n  '**它需要浏览器插件**（借 `ctx.browser` 服务）；没有时会给明确错误，不会假装能用。',\n  `投稿页：抖音 ${PLATFORMS.douyin.uploadUrl}；B站 ${PLATFORMS.bilibili.uploadUrl}。它自己开一个浏览器会话，登录态与其它会话共享。`,\n  '典型用法：`douyin_upload videoPath=<绝对路径> platform=\"bilibili\" title=…` → 看一眼回执与页面 → 确认无误后再 `mode: \"publish\"` 投出去。',\n  '遇到验证码/风控：它不会硬试 —— 请你到浏览器窗口里点一下，再让它继续。',\n].join('\\n');\n\n/** 动态取 defineTool：宿主里有就用真的，单测/CLI 场景退化成恒等。 */\nlet defineTool = (def) => def;\ntry {\n  const mod = await import('@deepseek-ai/dsh-tools');\n  if (mod && typeof mod.defineTool === 'function') defineTool = mod.defineTool;\n} catch {\n  /* 宿主外运行 */\n}\n\n/**\n * 取浏览器服务。官方的做法是 `ctx.get('browser')` —— 它不会因为\"没 inject\"而抛，\n * 拿不到就是 undefined，这正是我们要的降级姿势。\n * @param {object} ctx 宿主上下文\n * @returns {object|null} 服务或 null\n */\nexport function browserOf(ctx) {\n  try {\n    const browser = typeof ctx?.get === 'function' ? ctx.get('browser') : undefined;\n    if (browser !== null && browser !== undefined && typeof browser.open === 'function') return browser;\n  } catch {\n    /* 没有浏览器插件：当作没有 */\n  }\n  return null;\n}\n\n/**\n * 挂载插件。\n * @param {import('@deepseek-ai/cordis').Context} ctx 宿主上下文\n * @param {object} [config] 插件配置\n */\nexport function apply(ctx, config) {\n  const cfg = config ?? {};\n  if (cfg.enabled === false) return;\n  const disposers = [];\n\n  if (ctx.tools !== undefined && typeof ctx.tools.register === 'function') {\n    disposers.push(ctx.tools.register(defineTool({\n      name: 'douyin_upload',\n      description: [\n        '把本地视频送到投稿页：开页面 → **先自检版式（缺控件就当场报\"改版了\"）** → **把文件塞进页面自己的上传控件**（本机临时只读小服务 + DataTransfer，不弹系统对话框、不挡人；大文件或注入被拦才退回系统对话框+UI 自动化）→ 填标题 → **填文案 + 代填话题并回读** → 设可见性 → **按 coverTime 设封面帧（仅抖音，默认第 1 秒）** → **默认停在投稿前**。',\n        '**平台**：`douyin`（默认）与 `bilibili` 都在真机上核对过；B站的话题进「标签」（回车确认），可见范围在「更多设置 → 可见范围」。小红书 / X 未核对，传了会明确拒绝（不假装能用）。',\n        '**配乐**：默认不碰。想让**用户自己在抖音平台曲库里挑**，传 `pickMusic: true` —— 填完内容后它会把「添加音乐」面板打开然后停在发布前，由人点（不自动选、不发布，`mode=publish` 时忽略）。',\n        '**本地混音（可选）**：`bgmPath` 给一段本地音频就先用 ffmpeg 混好再上传（原视频不动），`bgmVolume` 默认 0.35 —— 这是\"不想用平台曲库\"时的另一条路。',\n        '**文案**：`description` 填进简介框，话题接在后面（B站进标签框）。',\n        '**默认保守**：可见性默认 private（仅自己可见）、模式默认 draft（**不点投稿**）。要真发必须显式 mode=\"publish\"；平台没有你要的可见性选项时会当场拒绝，不会偷偷按公开发出去。',\n        '需要浏览器插件（借 ctx.browser 服务）；没有时会明确报错。',\n        'dryRun=true 时只检查视频与计划，不打开页面、不点按钮、不交文件。',\n      ].join('\\n'),\n      timeoutMs: TOOL_TIMEOUT_MS,\n      parameters: {\n        videoPath: { type: 'string', description: '要发布的视频**绝对路径**（必填）' },\n        title: { type: 'string', description: '作品标题（不填就留空，由你在页面上补）' },\n        description: { type: 'string', description: '作品文案/简介（填进简介编辑框，话题接在后面）' },\n        topics: { type: 'string', description: '话题，逗号分隔（会代填进简介编辑框，并回读确认；没读到的会如实说）' },\n        bgmPath: { type: 'string', description: '可选：背景音乐文件的**绝对路径**（给了就先混音再上传，原视频不动）' },\n        pickMusic: { type: 'boolean', description: '可选：true = 填完内容后打开抖音的「添加音乐」面板并停在发布前，由用户自己在平台曲库里挑（不自动选、不发布）' },\n        musicSearch: { type: 'string', description: '可选：打开配乐面板后顺手在「搜索音乐」里搜这个词（不给就只把搜索框聚焦，由人自己输）' },\n        bgmVolume: { type: 'number', description: '配乐音量 0~2（默认 0.35；原视频有声则与原声混合）' },\n        platform: { type: 'string', description: '发布平台：douyin（默认）/ bilibili（这两个真机核对过）；xiaohongshu / x 会明确拒绝' },\n        coverTime: { type: 'number', description: '封面取第几秒的画帧（默认 1 —— 第 0 帧常是黑场；0 = 不动封面；仅抖音生效）' },\n        visibility: { type: 'string', description: `可见性：${Object.keys(VISIBILITY).join(' / ')}（默认 private = ${VISIBILITY.private.label}；B站只有 private→仅自己可见 / public→公开可见）` },\n        mode: { type: 'string', description: 'draft（默认，停在投稿前）| publish（显式点投稿）' },\n        dryRun: { type: 'boolean', description: 'true = 只检查视频与计划，不动手' },\n        timeoutSec: { type: 'number', description: '等编辑页的上限秒数（默认 60）' },\n        maxInjectBytes: { type: 'number', description: '注入上限字节数（默认 512MB）：超过就退回系统对话框那条路' },\n      },\n      output: {\n        schema: {\n          type: 'object',\n          additionalProperties: false,\n          properties: {\n            ok: { type: 'boolean', required: true },\n            data: { type: 'json' },\n            error: { type: 'string' },\n          },\n        },\n        render: (args, value) => [{ type: 'text', text: renderResult(value.data ?? null, args?.platform ?? cfg.platform) }],\n      },\n      async execute(args) {\n        const a = args ?? {};\n        try {\n          const data = await uploadVideo({\n            videoPath: a.videoPath,\n            title: a.title ?? cfg.title,\n            description: a.description,\n            topics: a.topics,\n            bgmPath: a.bgmPath,\n            bgmVolume: a.bgmVolume,\n            pickMusic: a.pickMusic === true,\n            musicSearch: a.musicSearch,\n            platform: a.platform ?? cfg.platform,\n            coverTime: a.coverTime ?? cfg.coverTime,\n            visibility: a.visibility ?? cfg.visibility,\n            mode: a.mode ?? cfg.mode,\n            dryRun: a.dryRun === true,\n            timeoutSec: a.timeoutSec ?? cfg.timeoutSec,\n            maxInjectBytes: a.maxInjectBytes ?? cfg.maxInjectBytes,\n          }, {\n            browser: browserOf(ctx),\n            ffprobe: cfg.ffprobe,\n          });\n          // **不能**写 `error: undefined`：宿主用 lossless-JSON 校验返回对象，\n          // JSON.stringify 会悄悄丢掉 undefined，校验器不会 —— 会被判 \"invalid output\"。\n          const out = { ok: data.ok === true, data };\n          if (out.ok !== true) out.error = String(data.error ?? '未完成');\n          return out;\n        } catch (err) {\n          return { ok: false, error: err instanceof Error ? err.message : String(err) };\n        }\n      },\n    })));\n  }\n\n  if (cfg.announceToAgent !== false && ctx.systemPrompt !== undefined\n    && typeof ctx.systemPrompt.section === 'function') {\n    disposers.push(ctx.systemPrompt.section({\n      name: 'plugin:douyin-publish',\n      order: SECTION_ORDER,\n      text: DOUYIN_GUIDANCE,\n    }));\n  }\n\n  if (typeof ctx.effect === 'function' && disposers.length > 0) {\n    ctx.effect(() => () => {\n      for (const dispose of disposers) {\n        try {\n          if (typeof dispose === 'function') dispose();\n        } catch {\n          /* 卸载失败不阻断其它清理 */\n        }\n      }\n    }, 'dsh-douyin-publish: teardown');\n  }\n}\n"
    },
    {
      "path": "lib/serve.js",
      "content": "/**\n * dsh-douyin-publish · serve —— 在 127.0.0.1 上把一个文件临时\"递\"给页面。\n *\n * 为什么需要它：网页的 `<input type=file>` 只认**本地文件路径**或**系统对话框**，\n * 而\"系统对话框\"这条路要靠 UI 自动化去填另一个进程的窗口 —— 脆、会挡人、要 PowerShell。\n * 换成这条路：本机起一个**只读、只服务这一个文件、带随机令牌**的小服务，页面自己\n * fetch 回来再塞进 input，全程不碰桌面。\n *\n * 三条硬约束（都是安全）：\n *   1. 只绑 127.0.0.1 —— 局域网够不着；\n *   2. 只服务 `/f/<随机令牌>/<文件名>` 这一条路由，别的路径一律 404，不列目录；\n *   3. 用完就关（`close()`），另外带空闲超时兜底，不会留下一个长期开着的小服务器。\n *\n * @module dsh-douyin-publish/serve\n */\n\nimport { createServer } from 'node:http';\nimport { createReadStream, statSync } from 'node:fs';\nimport { basename, extname } from 'node:path';\nimport { randomBytes } from 'node:crypto';\n\n/** 后缀 → MIME（只列投稿页会收的那些）。 */\nexport const MIME = Object.freeze({\n  '.mp4': 'video/mp4',\n  '.m4v': 'video/x-m4v',\n  '.mov': 'video/quicktime',\n  '.flv': 'video/x-flv',\n  '.webm': 'video/webm',\n  '.mkv': 'video/x-matroska',\n  '.avi': 'video/x-msvideo',\n  '.wmv': 'video/x-ms-wmv',\n  '.ts': 'video/mp2t',\n  '.mpg': 'video/mpeg',\n  '.mpeg': 'video/mpeg',\n  '.mpeg4': 'video/mp4',\n});\n\n/** 默认空闲上限：10 分钟没请求就自己关。 */\nexport const DEFAULT_TTL_MS = 10 * 60 * 1000;\n\n/**\n * 按后缀取 MIME。\n * @param {string} filePath 路径\n * @returns {string} MIME\n */\nexport function mimeOf(filePath) {\n  return MIME[extname(String(filePath)).toLowerCase()] ?? 'application/octet-stream';\n}\n\n/**\n * 起一个小服务，只把**一个文件**递给页面。\n *\n * @param {object} [options] 参数\n * @param {string} options.filePath 要递的文件（绝对路径）\n * @param {string} [options.host] 绑定地址（默认 127.0.0.1，别改）\n * @param {number} [options.port] 端口（默认 0 = 系统分配）\n * @param {number} [options.ttlMs] 空闲自动关闭（默认 10 分钟）\n * @returns {Promise<{url:string, port:number, bytes:number, route:string, close:()=>Promise<void>}>} 句柄\n */\nexport async function startFileServer(options = {}) {\n  const filePath = String(options.filePath ?? '');\n  if (filePath === '') throw new Error('startFileServer: filePath 必填');\n  const stat = statSync(filePath);\n  if (!stat.isFile()) throw new Error(`startFileServer: 不是文件：${filePath}`);\n  const host = options.host ?? '127.0.0.1';\n  const ttlMs = Number.isFinite(options.ttlMs) ? options.ttlMs : DEFAULT_TTL_MS;\n  const token = randomBytes(9).toString('hex');\n  const route = `/f/${token}/${encodeURIComponent(basename(filePath))}`;\n  const type = mimeOf(filePath);\n\n  let timer = null;\n  const armTimer = () => {\n    if (timer !== null) clearTimeout(timer);\n    timer = setTimeout(() => {\n      server.close(() => {});\n    }, ttlMs);\n    timer.unref?.();\n  };\n\n  const server = createServer((req, res) => {\n    armTimer();\n    const url = String(req.url ?? '');\n    const path = url.split('?')[0];\n    if (path !== route) {\n      res.writeHead(404, { 'Content-Type': 'text/plain', 'Access-Control-Allow-Origin': '*' });\n      res.end('not found');\n      return;\n    }\n    if (req.method === 'OPTIONS') {\n      res.writeHead(204, {\n        'Access-Control-Allow-Origin': '*',\n        'Access-Control-Allow-Methods': 'GET, HEAD, OPTIONS',\n        'Access-Control-Allow-Headers': '*',\n        'Access-Control-Allow-Private-Network': 'true',\n        'Access-Control-Max-Age': '600',\n      });\n      res.end();\n      return;\n    }\n    if (req.method !== 'GET' && req.method !== 'HEAD') {\n      res.writeHead(405, { 'Content-Type': 'text/plain', 'Access-Control-Allow-Origin': '*' });\n      res.end('method not allowed');\n      return;\n    }\n    const headers = {\n      'Content-Type': type,\n      'Content-Length': String(stat.size),\n      'Access-Control-Allow-Origin': '*',\n      'Access-Control-Allow-Headers': '*',\n      'Access-Control-Allow-Private-Network': 'true',\n      'Access-Control-Expose-Headers': 'Content-Length, Content-Type',\n      'Cache-Control': 'no-store',\n    };\n    res.writeHead(200, headers);\n    if (req.method === 'HEAD') {\n      res.end();\n      return;\n    }\n    const stream = createReadStream(filePath);\n    stream.on('error', () => {\n      try {\n        res.destroy();\n      } catch {\n        /* 连接已经断了 */\n      }\n    });\n    stream.pipe(res);\n  });\n\n  await new Promise((resolve, reject) => {\n    const onError = (err) => reject(err);\n    server.once('error', onError);\n    server.listen(Number.isFinite(options.port) ? options.port : 0, host, () => {\n      server.removeListener('error', onError);\n      resolve();\n    });\n  });\n  armTimer();\n\n  const address = server.address();\n  const port = typeof address === 'object' && address !== null ? address.port : 0;\n  const url = `http://${host}:${port}${route}`;\n\n  return {\n    url,\n    port,\n    bytes: stat.size,\n    route,\n    downMs: 0,\n    close() {\n      if (timer !== null) clearTimeout(timer);\n      timer = null;\n      return new Promise((resolve) => server.close(() => resolve()));\n    },\n  };\n}\n"
    },
    {
      "path": "lib/bgm.js",
      "content": "/**\n * dsh-douyin-publish · bgm —— 给视频配一段背景音乐（本地文件 → ffmpeg 混音）。\n *\n * 为什么在这里做而不是\"让用户自己剪\"：抖音投稿页的曲库是它的，插件点不了；\n * 但**视频自带音轨**照样能发出去 —— 所以最稳的配乐方式是上传前用 ffmpeg 混好。\n *\n * 两种情形分开处理（不然 amix 会因为\"没有输入流\"直接失败）：\n *   - 视频**有**音轨：`amix` 把原声与 BGM 混在一起（BGM 音量可调）；\n *   - 视频**没有**音轨：直接把 BGM 当音轨铺满整段。\n *\n * 只写一个新文件到临时目录，**不动原视频**。\n *\n * @module dsh-douyin-publish/bgm\n */\n\nimport { spawn as nodeSpawn } from 'node:child_process';\nimport { join } from 'node:path';\nimport { tmpdir } from 'node:os';\n\n/** 默认 BGM 音量（0~1）。人声为主的视频不要盖过原声。 */\nexport const DEFAULT_BGM_VOLUME = 0.35;\n\n/**\n * ffmpeg 在哪：显式参数 → 环境变量 → PATH。\n * @param {string} [explicit] 显式\n * @returns {string} 路径\n */\nexport function resolveFfmpeg(explicit) {\n  if (typeof explicit === 'string' && explicit !== '') return explicit;\n  if (typeof process.env.DSH_FFMPEG_PATH === 'string' && process.env.DSH_FFMPEG_PATH !== '') {\n    return process.env.DSH_FFMPEG_PATH;\n  }\n  return 'ffmpeg';\n}\n\n/**\n * 跑一个进程并收全输出（与 video.js 同款，独立一份，避免互相牵连）。\n * @param {Function} spawnImpl spawn\n * @param {string} command 命令\n * @param {string[]} args 参数\n * @param {number} timeoutMs 上限\n * @returns {Promise<{code:number, stdout:string, stderr:string}>} 结果\n */\nfunction collect(spawnImpl, command, args, timeoutMs) {\n  return new Promise((resolve) => {\n    let child;\n    try {\n      child = spawnImpl(command, args, { windowsHide: true, timeout: timeoutMs });\n    } catch (err) {\n      resolve({ code: -1, stdout: '', stderr: err instanceof Error ? err.message : String(err) });\n      return;\n    }\n    let stdout = '';\n    let stderr = '';\n    child.stdout?.on?.('data', (chunk) => { stdout += chunk.toString(); });\n    child.stderr?.on?.('data', (chunk) => { stderr += chunk.toString(); });\n    child.on?.('error', (err) => resolve({ code: -1, stdout, stderr: `${stderr}${err instanceof Error ? err.message : String(err)}` }));\n    child.on?.('close', (code) => resolve({ code: typeof code === 'number' ? code : -1, stdout, stderr }));\n  });\n}\n\n/**\n * 视频里有没有音轨。\n * @param {Function} spawnImpl spawn\n * @param {string} ffprobe ffprobe\n * @param {string} path 视频\n * @returns {Promise<boolean>} 有没有\n */\nexport async function hasAudioTrack(spawnImpl, ffprobe, path) {\n  const res = await collect(spawnImpl, ffprobe, [\n    '-v', 'error', '-select_streams', 'a:0', '-show_entries', 'stream=codec_name', '-of', 'json', path,\n  ], 20000);\n  if (res.code !== 0) return false;\n  try {\n    const parsed = JSON.parse(res.stdout);\n    return Array.isArray(parsed?.streams) && parsed.streams.length > 0;\n  } catch {\n    return false;\n  }\n}\n\n/**\n * 拼 ffmpeg 参数（纯函数，便于单测断言）。\n * @param {{videoPath:string,bgmPath:string,outPath:string,volume:number,videoHasAudio:boolean}} input 输入\n * @returns {string[]} 参数\n */\nexport function buildMixArgs({ videoPath, bgmPath, outPath, volume, videoHasAudio }) {\n  const gain = Math.max(0, Math.min(2, Number(volume)));\n  const base = ['-y', '-i', videoPath, '-stream_loop', '-1', '-i', bgmPath];\n  if (videoHasAudio) {\n    return [\n      ...base,\n      '-filter_complex',\n      `[1:a]volume=${gain}[bg];[0:a][bg]amix=inputs=2:duration=first:dropout_transition=0[aout]`,\n      '-map', '0:v:0', '-map', '[aout]',\n      '-c:v', 'copy', '-c:a', 'aac', '-b:a', '192k', '-shortest', outPath,\n    ];\n  }\n  return [\n    ...base,\n    '-filter_complex', `[1:a]volume=${gain}[aout]`,\n    '-map', '0:v:0', '-map', '[aout]',\n    '-c:v', 'copy', '-c:a', 'aac', '-b:a', '192k', '-shortest', outPath,\n  ];\n}\n\n/**\n * 混一段 BGM 进视频，输出到临时目录。\n * @param {{videoPath:string,bgmPath:string,volume?:number,ffmpeg?:string,ffprobe?:string,spawnImpl?:Function,tmpDir?:string}} input 输入\n * @returns {Promise<{ok:boolean, outputPath?:string, volume?:number, videoHadAudio?:boolean, error?:string, stderrTail?:string}>} 结果\n */\nexport async function mixBgm(input) {\n  const spawnImpl = input.spawnImpl ?? nodeSpawn;\n  const ffmpeg = resolveFfmpeg(input.ffmpeg);\n  const ffprobe = input.ffprobe ?? 'ffprobe';\n  const volume = Number.isFinite(input.volume) ? Number(input.volume) : DEFAULT_BGM_VOLUME;\n  const outPath = join(input.tmpDir ?? tmpdir(), `dsh-douyin-bgm-${Date.now()}.mp4`);\n\n  const videoHasAudio = await hasAudioTrack(spawnImpl, ffprobe, input.videoPath);\n  const args = buildMixArgs({ videoPath: input.videoPath, bgmPath: input.bgmPath, outPath, volume, videoHasAudio });\n  const res = await collect(spawnImpl, ffmpeg, args, 300000);\n  if (res.code !== 0) {\n    return {\n      ok: false,\n      error: `ffmpeg 混音失败（exit ${res.code}）`,\n      stderrTail: res.stderr.split('\\n').slice(-4).join(' | ').slice(0, 400),\n      videoHadAudio: videoHasAudio,\n    };\n  }\n  return { ok: true, outputPath: outPath, volume, videoHadAudio: videoHasAudio };\n}\n"
    }
